    static long[] queryResult;
    static long[] prefix;
    static final int SHIFT = 20;
    static final int OFFSET = 1_000_000_000;

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader();
        N = sc.nextInt();
        Q = sc.nextInt();
        K = sc.nextInt();
        A = new int[N + 1];
        u = new int[N + 1];
        v = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            A[i] = sc.nextInt();
            u[i] = i + A[i];
            v[i] = i - A[i];
        }
        D = new int[Q + 1];
        deleted = new boolean[N + 1];
        for (int t = 1; t <= Q; t++) {
            D[t] = sc.nextInt();
            deleted[D[t]] = true;
        }

        // Build packed arrays for u and v
        long[] uArr = new long[N];
        long[] vArr = new long[N];
        for (int i = 1; i <= N; i++) {
            uArr[i - 1] = ((long) u[i] << SHIFT) | i;
            vArr[i - 1] = ((long) (v[i] + OFFSET) << SHIFT) | i;
        }
        Arrays.sort(uArr);
        Arrays.sort(vArr);

        // Initialize DSU
        parent = new int[N + 1];
        size = new int[N + 1];
        L = new int[N + 1];
        R = new int[N + 1];
        active = new boolean[N + 1];
        for (int i = 1; i <= N; i++) {
            parent[i] = i;
            size[i] = 1;
            L[i] = i;
            R[i] = i;
        }

        qL1 = new int[N];
        qR1 = new int[N];
        qL2 = new int[N];
        qR2 = new int[N];
        queryCount = 0;
        queryCountAfterActivation = new int[N + 1];

        int step = 0;
        // Activate non-deleted positions
        for (int pos = 1; pos <= N; pos++) {
            if (!deleted[pos]) {
                activate(pos);
                step++;
                queryCountAfterActivation[step] = queryCount;
            }
        }
        // Activate deleted positions in reverse order
        for (int t = Q; t >= 1; t--) {
            int pos = D[t];
            activate(pos);
            step++;
            queryCountAfterActivation[step] = queryCount;
        }

        queryResult = new long[queryCount];
        for (int q = 0; q < queryCount; q++) {
            int L1 = qL1[q], R1 = qR1[q], L2 = qL2[q], R2 = qR2[q];
            long count = 0;
            int sizeL = R1 - L1 + 1;
            int sizeR = R2 - L2 + 1;
            if (sizeL <= sizeR) {
                for (int i = L1; i <= R1; i++) {
                    // i in left, j in right
                    count += countInRange(uArr, u[i] + K, L2, Math.min(R2, i + K), 0);
                    count += countInRange(vArr, v[i] + K, L2, Math.min(R2, i + K - 1), OFFSET);
                }
            } else {
                for (int i = L2; i <= R2; i++) {
                    // i in right, j in left
                    count += countInRange(uArr, u[i] - K, Math.max(L1, i - K), R1, 0);
                    count += countInRange(vArr, v[i] - K, Math.max(L1, i - K + 1), R1, OFFSET);
                }
            }
            queryResult[q] = count;
        }

        prefix = new long[queryCount + 1];
        for (int i = 0; i < queryCount; i++) {
            prefix[i + 1] = prefix[i] + queryResult[i];
        }

        long[] totalAfterActivation = new long[N + 1];
        for (int s = 0; s <= N; s++) {
            totalAfterActivation[s] = prefix[queryCountAfterActivation[s]];
        }

        StringBuilder sb = new StringBuilder();
        for (int t = 0; t <= Q; t++) {
            sb.append(totalAfterActivation[N - t]).append('\n');
        }
        System.out.print(sb);
    }

    static void activate(int pos) {
        active[pos] = true;
        parent[pos] = pos;
        size[pos] = 1;
        L[pos] = pos;
        R[pos] = pos;

        if (pos > 1 && active[pos - 1]) {
            int leftRoot = find(pos - 1);
            qL1[queryCount] = L[leftRoot];
            qR1[queryCount] = R[leftRoot];
            qL2[queryCount] = pos;
            qR2[queryCount] = pos;
            queryCount++;
            union(leftRoot, pos);
        }
        if (pos < N && active[pos + 1]) {
            int rightRoot = find(pos + 1);
            int curRoot = find(pos);
            qL1[queryCount] = L[curRoot];
            qR1[queryCount] = R[curRoot];
            qL2[queryCount] = L[rightRoot];
            qR2[queryCount] = R[rightRoot];
            queryCount++;
            union(curRoot, rightRoot);
        }
    }

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static void union(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra;
            ra = rb;
            rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
        if (L[rb] < L[ra]) L[ra] = L[rb];
        if (R[rb] > R[ra]) R[ra] = R[rb];
    }

    static int countInRange(long[] arr, int targetVal, int low, int high, int offset) {
        if (low > high) return 0;
        int val = targetVal + offset;
        if (val < 0) return 0;
        long key = ((long) val) << SHIFT;
        int left = lowerBound(arr, key);
        int right = lowerBound(arr, key + (1L << SHIFT));
        if (left >= right) return 0;
        int idxLow = lowerBound(arr, left, right, key | low);
        int idxHigh = lowerBound(arr, left, right, key | (high + 1));
        return idxHigh - idxLow;
    }

    static int lowerBound(long[] arr, long key) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int lowerBound(long[] arr, int from, int to, long key) {
        int lo = from, hi = to;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
